const map = L.map('map', { worldCopyJump: true, minZoom: 2, zoomControl: false }).setView([27, 8], 2);
L.control.zoom({ position: 'bottomright' }).addTo(map);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 18, attribution: '&copy; OpenStreetMap contributors' }).addTo(map);
const cluster = L.markerClusterGroup({ showCoverageOnHover: false, maxClusterRadius: 48, spiderfyOnMaxZoom: true, disableClusteringAtZoom: 10 });
const safe = (value = '') => String(value).replace(/[&<>'"]/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const linkedIn = (url = '') => { if (!url) return ''; const normalized = /^https?:\/\//i.test(url) ? url : `https://${url}`; try { return new URL(normalized).hostname.toLowerCase().endsWith('linkedin.com') ? normalized : ''; } catch { return ''; } };
const colorForLongitude = (lng) => { const now = new Date(); const local = (now.getUTCHours() + now.getUTCMinutes() / 60 + lng / 15 + 24) % 24; if (local >= 6 && local < 10) return '#ffd500'; if (local >= 10 && local < 17) return '#ffbf00'; if (local >= 17 && local < 21) return '#ff5634'; return '#7d83ff'; };
const iconFor = (lng) => L.divIcon({ className: '', iconSize: [42, 55], iconAnchor: [21, 54], popupAnchor: [0, -45], html: `<div class="agent-pin" style="--pin:${colorForLongitude(lng)}"><span class="glo-pin"></span></div>` });
let members = []; let markers = [];
const search = document.querySelector('#place'); const results = document.querySelector('#results');
function openMember(member) { const marker = markers.find((item) => item.member.id === member.id)?.marker; if (!marker) return; map.setView(marker.getLatLng(), Math.max(map.getZoom(), 7), { animate: true }); cluster.zoomToShowLayer(marker, () => marker.openPopup()); results.classList.remove('active'); }
function renderResults(query) { const q = query.trim().toLowerCase(); if (!q) { results.classList.remove('active'); results.innerHTML = ''; return; } const hits = members.filter((m) => [m.name,m.company,m.title,m.location,m.geo?.label,m.geo?.country].join(' ').toLowerCase().includes(q)).slice(0, 8); results.innerHTML = hits.length ? hits.map((m) => `<button class="result" role="option" data-id="${m.id}"><strong>${safe(m.name || 'Cohort member')}</strong><small>${safe(m.location || m.geo?.label || '')}</small></button>`).join('') : '<div class="result"><small>No matching members or places</small></div>'; results.classList.add('active'); }
search.addEventListener('input', (event) => renderResults(event.target.value));
search.addEventListener('keydown', (event) => { if (event.key === 'Escape') { search.value=''; renderResults(''); } });
results.addEventListener('click', (event) => { const button = event.target.closest('[data-id]'); if (button) openMember(members.find((m) => m.id === Number(button.dataset.id))); });
document.addEventListener('click', (event) => { if (!event.target.closest('.map-panel')) results.classList.remove('active'); });
fetch('./students.json').then((response) => response.json()).then((data) => {
  members = data; const mapped = members.filter((member) => member.geo); const places = new Set(mapped.map((member) => member.geo.label)); const countries = new Set(mapped.map((member) => member.geo.country).filter(Boolean));
  document.querySelector('#studentCount').textContent = members.length; document.querySelector('#placeCount').textContent = places.size; document.querySelector('#countryCount').textContent = countries.size; document.querySelector('#dataNote').textContent = `${members.length - mapped.length} profiles are waiting for a location.`;
  mapped.forEach((member) => { const url = linkedIn(member.linkedin); const marker = L.marker([member.geo.lat, member.geo.lng], { icon: iconFor(member.geo.lng), title: member.name || 'Cohort member' }); marker.bindPopup(`<article class="profile"><h3>${safe(member.name || 'Cohort member')}</h3><p class="role">${safe(member.title || 'Building with agents')}${member.company ? ` · ${safe(member.company)}` : ''}</p><p class="place">${safe(member.location || member.geo.label)}</p>${url ? `<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">View LinkedIn</a>` : ''}</article>`); marker.on('mouseover', () => marker.openPopup()); markers.push({ member, marker }); cluster.addLayer(marker); }); map.addLayer(cluster);
}).catch(() => { document.querySelector('#dataNote').textContent = 'The cohort map could not load. Please refresh.'; });
